import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useNavigate, useParams } from "react-router-dom";
import private_api from "../../server/private_api";

const LecionaLista = () => {
  const [cursos, setCursos] = useState([]);
  const [alunos, setAlunos] = useState([]);
  const [selectedCurso, setSelectedCurso] = useState("");
  const [loading, setLoading] = useState(true);
  const [loadingAlunos, setLoadingAlunos] = useState(false);
  const navigate = useNavigate();
  const { id } = useParams();

  const fetchCursos = async () => {
    try {
      const resposta = await private_api.get(`/professores/${id}/listacursos`);
      if (resposta.status === 200) {
        setCursos(resposta.data);
      } else {
        console.error("Erro ao buscar cursos");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchAlunosDoCurso = async (cursoId) => {
    if (!cursoId) return;

    setLoadingAlunos(true);
    try {
      const resposta = await private_api.get(`/cursos/${cursoId}/alunos`);
      if (resposta.status === 200) {
        setAlunos(resposta.data);
      } else {
        console.error("Erro ao buscar alunos");
        setAlunos([]);
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
      setAlunos([]);
    } finally {
      setLoadingAlunos(false);
    }
  };

  useEffect(() => {
    if (id) {
      fetchCursos();
    } else {
      setLoading(false);
    }
  }, [id]);

  const handleCursoChange = (e) => {
    const cursoId = e.target.value;
    setSelectedCurso(cursoId);
    fetchAlunosDoCurso(cursoId);
  };

  if (loading) {
    return (
      <div className="d-flex justify-content-center mt-5">Carregando...</div>
    );
  }

  return (
    <div
      className="container-fluid d-flex flex-column align-items-center"
      style={{
        backgroundColor: "#E7EFF4",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      <nav className="nav nav-tabs mb-3 bg-white p-2 w-75 d-flex justify-content-center">
        <a className="nav-link active mx-3" href="">
          Cursos
        </a>
        <a
          className="nav-link mx-3"
          href=""
          onClick={() => navigate(`/lecionaaula/${id}`)}
        >
          Aulas
        </a>
        <a
          className="nav-link mx-3"
          href=""
          onClick={() => navigate(`/lecionaavaliacao/${id}`)}
        >
          Avaliações
        </a>
      </nav>

      <h2 className="mb-3 text-center">Lista de Cursos à lecionar</h2>
      <table className="table table-bordered bg-white w-75 mb-4">
        <thead>
          <tr>
            <th>Curso</th>
            <th>Nível</th>
            <th>Data de Início</th>
            <th>Data de Fim</th>
            <th>Período</th>
          </tr>
        </thead>
        <tbody>
          {cursos.length > 0 ? (
            cursos.map((curso) => (
              <tr key={curso.id}>
                <td>{curso.nome}</td>
                <td>{curso.nivel}</td>
                <td>{new Date(curso.dataInicio).toLocaleDateString()}</td>
                <td>{new Date(curso.dataFim).toLocaleDateString()}</td>
                <td>{curso.periodo}</td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="5" className="text-center">
                Nenhum curso encontrado
              </td>
            </tr>
          )}
        </tbody>
      </table>

      <div className="w-75 mb-4">
        <h3 className="mb-3 text-center">Alunos por Curso</h3>
        <div className="mb-3">
          <label htmlFor="cursoSelect" className="form-label">
            Selecione um curso:
          </label>
          <select
            id="cursoSelect"
            className="form-select"
            value={selectedCurso}
            onChange={handleCursoChange}
          >
            <option value="">Selecione um curso</option>
            {cursos.map((curso) => (
              <option key={curso.id} value={curso.id}>
                {curso.nome} - {curso.periodo}
              </option>
            ))}
          </select>
        </div>

        {loadingAlunos ? (
          <div className="d-flex justify-content-center mt-3">
            Carregando alunos...
          </div>
        ) : (
          <table className="table table-bordered bg-white">
            <thead>
              <tr>
                <th>Nome</th>
                <th>Email</th>
                <th>Contacto</th>
              </tr>
            </thead>
            <tbody>
              {alunos.length > 0 ? (
                alunos.map((aluno) => (
                  <tr key={aluno.id}>
                    <td>{aluno.nome}</td>
                    <td>{aluno.email}</td>
                    <td>{aluno.contacto}</td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan="3" className="text-center">
                    {selectedCurso
                      ? "Nenhum aluno encontrado neste curso"
                      : "Selecione um curso para ver os alunos"}
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
};

export default LecionaLista;
